import {buildWhatsAppMessage,whatsappURL} from './whatsapp.js';
const $=s=>document.querySelector(s), main=$('#main'),modal=$('#modal'),content=$('#modal-content');
const money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let store,user,admin,adminTab='products',chosenSize,detailId,coupon='',lastQuote,toastTimer;
let cart;try{cart=JSON.parse(localStorage.getItem('gym-cart')||'[]');if(!Array.isArray(cart))cart=[];}catch{cart=[];}
async function api(path,method='GET',body){const r=await fetch('/api'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw Error(data.error||'Não foi possível concluir.');return data;}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5000);}
function persist(){document.querySelectorAll('.mobile-bag-count').forEach(x=>x.textContent=cart.reduce((a,i)=>a+i.quantity,0));try{localStorage.setItem('gym-cart',JSON.stringify(cart));}catch{}document.querySelectorAll('.cart-count').forEach(x=>x.textContent=cart.reduce((a,i)=>a+i.quantity,0));}
function show(html){modal.classList.toggle('product-modal',html.includes('product-detail'));content.innerHTML=html;if(!modal.open)modal.showModal();}
function field(label,name,value='',type='text',extra=''){return `<label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`;}
function productCard(p){return `<article class="product"><a href="#product=${p.id}" class="product-image"><img src="${esc(p.images[0])}" alt="${esc(p.name)} — foto ilustrativa" loading="lazy" width="400" height="400">${p.tag?`<span class="tag">${esc(p.tag)}</span>`:''}</a><p class="type">${esc(p.category)} / EXEMPLO</p><h3><a href="#product=${p.id}">${esc(p.name)}</a></h3><div class="prices"><strong>${money(p.price)}</strong>${p.oldPrice>p.price?`<del>${money(p.oldPrice)}</del>`:''}</div><small>Modelo de exemplo</small><a class="choose" href="#product=${p.id}">Ver tamanhos</a></article>`;}
const normalizeSearch=value=>String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function matchesShoeSearch(product,query){const name=normalizeSearch(product.name);return normalizeSearch(query).trim().split(/\s+/).every(word=>name.includes(word));}
function renderHomeProducts(){const query=$('#shoe-search')?.value||'';const category=document.querySelector('[data-action="home-filter"].active')?.dataset.category||'';const products=store.products.filter(p=>(!category||p.category===category)&&matchesShoeSearch(p,query));$('#home-products').innerHTML=products.length?products.map(productCard).join(''):'<div class="empty search-empty">Nenhum tênis encontrado. Tente outro nome ou marca.</div>';$('#home-search-count').textContent=query?`${products.length} tênis encontrado(s)`:'';}
function home(){main.innerHTML=`<section class="welcome-banner" aria-labelledby="welcome-title"><img class="welcome-art" src="${esc(store.banners.image)}" alt="Campanha GYM STORE" fetchpriority="high" width="1000" height="800"><div class="welcome-copy"><span class="welcome-label">${esc(store.banners.eyebrow)}</span><h1 id="welcome-title">${esc(store.banners.title)}</h1><p>${esc(store.banners.subtitle)}</p><a href="#catalog" class="btn welcome-button">Conheça os modelos</a></div></section><section class="section wrap home-catalog"><div class="section-title"><h2>Nossos tênis</h2><a href="#catalog">Ver filtros</a></div><div class="catalog-search"><label for="shoe-search">Pesquisar tênis pelo nome</label><div class="search-row"><input type="search" id="shoe-search" placeholder="Digite o nome ou a marca do tênis..." autocomplete="off" enterkeyhint="search"><button type="button" data-action="clear-shoe-search">Limpar</button></div><p id="home-search-count" class="small-text" aria-live="polite"></p></div><div class="tabs" aria-label="Filtrar tênis por categoria"><button class="pill active" data-action="home-filter" data-category="">Todos</button>${store.categories.map(c=>`<button class="pill" data-action="home-filter" data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="products" id="home-products">${store.products.map(productCard).join('')}</div><div class="simple-help"><strong>Como comprar?</strong><p>Escolha o tênis e o tamanho, adicione à sacola e envie seu pedido pelo WhatsApp.</p></div></section><p class="wrap demo-note">Catálogo de exemplo. Fotos, valores e estoque ilustrativos.</p>`;}
function catalog(params){const c=params.get('category')||'',tag=params.get('tag')||'',q=params.get('q')||'';main.innerHTML=`<section class="wrap catalog-head"><div class="breadcrumb"><a href="#home">Início</a> / Coleção</div><span class="eyebrow">CATÁLOGO GYM STORE</span><h1>${esc(q?'Busca: '+q:c||tag||'Todos os tênis')}.</h1><p>Escolha sua categoria, tamanho e faixa de preço.</p><div class="catalog-search"><label for="catalog-name-search">Pesquisar tênis pelo nome</label><div class="search-row"><input type="search" id="catalog-name-search" value="${esc(q)}" placeholder="Digite o nome ou a marca do tênis..." autocomplete="off" enterkeyhint="search"><button type="button" data-action="clear-shoe-search">Limpar</button></div></div><div class="filters"><select id="filter-category" aria-label="Categoria"><option value="">Todas as categorias</option>${store.categories.map(x=>`<option ${x===c?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="filter-size" aria-label="Numeração"><option value="">Todas as numerações</option>${Array.from({length:10},(_,i)=>`<option>${i+34}</option>`).join('')}</select><select id="filter-price" aria-label="Faixa de preço"><option value="">Todos os preços</option><option value="20000">Até R$ 200</option><option value="25000">Até R$ 250</option><option value="30000">Até R$ 300</option></select><select id="filter-sort" aria-label="Ordenar"><option value="featured">Recomendados</option><option value="asc">Menor preço</option><option value="desc">Maior preço</option><option value="name">Nome A–Z</option></select><span class="count" id="result-count"></span></div><div class="products" id="catalog-products"></div></section>`;const render=()=>{let p=store.products.filter(p=>(!$('#filter-category').value||p.category===$('#filter-category').value)&&(!tag||p.tag===tag)&&matchesShoeSearch(p,$('#catalog-name-search').value)&&(!$('#filter-size').value||p.sizes[$('#filter-size').value]>0)&&(!$('#filter-price').value||p.price<=Number($('#filter-price').value)));const sort=$('#filter-sort').value;if(sort==='asc')p.sort((a,b)=>a.price-b.price);if(sort==='desc')p.sort((a,b)=>b.price-a.price);if(sort==='name')p.sort((a,b)=>a.name.localeCompare(b.name));$('#catalog-products').innerHTML=p.length?p.map(productCard).join(''):'<p class="empty">Nenhum tênis encontrado. Experimente outros filtros.</p>';$('#result-count').textContent=`${p.length} produtos de exemplo`;};document.querySelectorAll('.filters select').forEach(x=>x.onchange=render);$('#catalog-name-search').oninput=render;render();}
function detail(id){const p=store.products.find(x=>x.id===id);if(!p){toast('Produto indisponível.');return;}detailId=id;chosenSize=null;const discount=p.oldPrice>p.price?Math.round((1-p.price/p.oldPrice)*100):0;show(`<div class="product-detail"><div class="detail-topline"><span>GYM STORE</span><span>Detalhes do tênis</span></div><div class="detail product-detail-grid"><div class="detail-visual"><div class="detail-photo-wrap"><img class="detail-image" src="${esc(p.images[0])}" alt="${esc(p.name)}">${p.tag?`<span class="detail-photo-tag">${esc(p.tag)}</span>`:''}</div>${p.images.length>1?`<div class="gallery">${p.images.map((im,i)=>`<button class="${i===0?'selected':''}" data-action="photo" data-index="${i}" aria-label="Ver foto ${i+1}" aria-pressed="${i===0}"><img src="${esc(im)}" alt="Foto ${i+1}"></button>`).join('')}</div>`:''}<p class="detail-photo-caption">Fotografia ilustrativa · Produto de exemplo</p></div><div class="detail-info"><div class="detail-category">${esc(p.category)} <span>•</span> ${esc(p.color)}</div><h2 id="detail-title">${esc(p.name)}</h2><div class="detail-price-card">${discount?`<div class="detail-old-price"><del>${money(p.oldPrice)}</del><span>${discount}% de desconto</span></div>`:''}<strong>${money(p.price)}</strong><p>Valor do produto · frete a combinar</p></div><div class="detail-color"><span>Cor escolhida</span><b>${esc(p.color)}</b></div><div class="detail-size-heading"><strong>Escolha seu tamanho</strong><span id="selected-size">Selecione abaixo</span></div><div class="sizes" role="group" aria-label="Numeração disponível">${Object.entries(p.sizes).map(([size,n])=>`<button class="size" data-action="size" data-size="${size}" aria-pressed="false" ${n?'':'disabled'}>${size}</button>`).join('')}</div><div class="detail-order"><div class="detail-quantity-line"><label for="quantity">Quantidade</label><div class="detail-stepper"><button data-action="detail-qty" data-delta="-1" aria-label="Diminuir quantidade">−</button><input id="quantity" value="1" type="number" min="1" max="20" readonly aria-label="Quantidade escolhida"><button data-action="detail-qty" data-delta="1" aria-label="Aumentar quantidade">+</button></div></div><button class="btn detail-add" data-action="add"><svg width="19" height="20" viewBox="0 0 24 26" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M4 8h16l1 16H3L4 8Z"/><path d="M8 9V6a4 4 0 0 1 8 0v3"/></svg>Adicionar à sacola <span id="detail-line-total">${money(p.price)}</span></button><p class="detail-size-hint">Escolha a numeração antes de adicionar.</p></div><div class="detail-service"><span aria-hidden="true">↗</span><div><strong>Finalize pelo WhatsApp</strong><p>Confira sua sacola e combine pagamento e entrega com a loja.</p></div></div><details class="detail-description"><summary>Sobre este tênis <span aria-hidden="true">+</span></summary><p>${esc(p.description)}</p></details><details class="detail-description"><summary>Entrega e pagamento <span aria-hidden="true">+</span></summary><p>Frete, disponibilidade e forma de pagamento serão confirmados no atendimento pelo WhatsApp. Nenhuma cobrança é feita no site.</p></details><p class="detail-example">Catálogo demonstrativo. Fotos, preços e estoque são exemplos.</p></div></div></div>`);}
function totalsHTML(q){return `<div><span>Subtotal</span><span>${money(q.subtotal)}</span></div><div><span>Desconto ${esc(q.coupon||'')}</span><span>− ${money(q.discount)}</span></div><div><span>Frete</span><span>A combinar pelo WhatsApp</span></div><div class="total"><span>Total sem frete</span><strong>${money(q.total)}</strong></div>`;}
async function openCart(){show('<h2>Sua sacola</h2><p class="small-text">Carregando…</p>');if(!cart.length){content.innerHTML='<h2>Sua sacola está vazia.</h2><p>O seu próximo favorito está por aqui.</p><button class="btn" data-action="shop">Explorar coleção ↗</button>';return;}const lines=cart.map((i,index)=>{const p=store.products.find(p=>p.id===i.productId);return `<div class="cart-line"><img src="${esc(p?.images[0]||'/assets/logo.webp')}" alt="${esc(p?.name||'Produto indisponível')}"><div><h3>${esc(p?.name||'Produto indisponível')}</h3><p>Tamanho ${esc(i.size)} • ${esc(p?.color||'')}</p><div class="qty"><button data-action="qty" data-index="${index}" data-delta="-1" aria-label="Diminuir quantidade">−</button><span>${i.quantity}</span><button data-action="qty" data-index="${index}" data-delta="1" aria-label="Aumentar quantidade">+</button></div><button class="remove" data-action="remove" data-index="${index}">Remover</button></div><strong>${money((p?.price||0)*i.quantity)}</strong></div>`;}).join('');let err='';try{lastQuote=await api('/quote','POST',{items:cart,coupon});}catch(e){lastQuote=null;err=e.message;}content.innerHTML=`<h2>Sua sacola <span class="small-text">(${cart.reduce((s,i)=>s+i.quantity,0)} itens)</span></h2>${lines}<form id="coupon" class="inline-form"><input name="coupon" aria-label="Cupom" value="${esc(coupon)}" placeholder="Cupom de desconto"><button class="btn light">Aplicar</button></form><p class="small-text">Experimente GYM10: 10% de desconto no catálogo de exemplo.</p>${err?`<p class="error">${esc(err)} <button data-action="clear-coupon">Remover cupom</button></p>`:''}<div class="summary">${lastQuote?totalsHTML(lastQuote):''}</div><button class="btn" data-action="checkout" ${lastQuote?'':'disabled'}>Pedir pelo WhatsApp ↗</button><div class="notice">O pedido será combinado pelo WhatsApp. Produtos e preços desta prévia são exemplos.</div>`;}
function auth(mode='login'){const register=mode==='register',forgot=mode==='forgot';show(`<form id="auth" class="form" data-mode="${mode}"><span class="eyebrow">BEM-VINDO À GYM STORE</span><h2>${register?'Crie sua conta':forgot?'Recuperar senha':'Seu próximo passo começa aqui.'}</h2>${register?field('Seu nome','name','','text','required autocomplete="name" maxlength="100"'):''}${field('E-mail','email','','email','required autocomplete="email"')}${!forgot?field('Senha'+(register?' (mínimo 10 caracteres)':''),'password','','password',`required ${register?'minlength="10" autocomplete="new-password"':'autocomplete="current-password"'} maxlength="128"`):''}<p id="form-error" class="error" role="alert"></p><button class="btn">${register?'Criar conta':forgot?'Enviar instruções':'Entrar'} ↗</button><div class="form-links"><button type="button" data-action="auth" data-mode="${register?'login':'register'}">${register?'Já tenho uma conta':'Criar minha conta'}</button><button type="button" data-action="auth" data-mode="forgot">Esqueci minha senha</button></div>${register?'<p class="small-text">Nesta versão, use apenas dados fictícios para testes.</p>':''}</form>`);}
async function account(){if(!user){main.innerHTML='<div class="wrap page"><h1>Minha conta</h1><p>Entre para acessar seus dados, endereços e pedidos.</p><button class="btn" data-action="auth" data-mode="login">Entrar na conta</button></div>';auth();return;}const {orders}=await api('/orders');main.innerHTML=`<section class="wrap page"><div class="breadcrumb"><a href="#home">Início</a> / Minha conta</div><h1>Olá, ${esc(user.name.split(' ')[0])}.</h1><div class="account-layout"><aside class="account-nav"><a href="#account">Dados e pedidos</a>${['owner','manager','admin'].includes(user.role)?'<a href="#admin">Painel administrativo ↗</a>':''}<button data-action="logout">Sair da conta</button></aside><div><div class="panel"><h2>Meus dados</h2><form id="profile" class="form">${field('Nome','name',user.name,'text','required')}${field('E-mail','email',user.email,'email','disabled')}${field('Telefone','phone',user.phone,'tel')}<button class="btn light">Salvar dados</button></form></div><div class="panel"><h2>Meus endereços</h2>${user.addresses.length?user.addresses.map((a,i)=>`<p class="small-text"><b>${esc(a.name)}</b> — ${esc(a.street)}, ${esc(a.number)} ${esc(a.complement)}<br>${esc(a.district)}, ${esc(a.city)} / ${esc(a.state)} — ${esc(a.cep)} <button data-action="delete-address" data-index="${i}">Remover</button></p>`).join(''):'<p class="small-text">Nenhum endereço cadastrado.</p>'}<button class="btn light" data-action="address">Adicionar endereço</button></div><div class="panel"><h2>Histórico de pedidos</h2>${orders.length?orders.map(o=>`<div class="panel"><strong>${esc(o.id)}</strong><p class="small-text">${new Date(o.createdAt).toLocaleDateString('pt-BR')} • ${esc(o.status)} • ${money(o.total)}</p>${o.items.map(i=>`<p>${i.quantity}× ${esc(i.name)} — ${esc(i.size)}</p>`).join('')}<span class="fine">PEDIDO DE TESTE / SEM COBRANÇA</span></div>`).join(''):'<p class="small-text">Seus pedidos aparecerão aqui.</p>'}</div></div></div></section>`;}
function addressFields(a={}){return `${field('Nome do endereço','name',a.name||'Casa','text','required')}${field('CEP','cep',a.cep,'text','required pattern="[0-9]{5}-?[0-9]{3}" inputmode="numeric" maxlength="9"')}${field('Rua / avenida','street',a.street,'text','required autocomplete="address-line1"')}<div class="two"><div>${field('Número','number',a.number,'text','required')}</div><div>${field('Complemento','complement',a.complement)}</div></div>${field('Bairro','district',a.district,'text','required')}<div class="two"><div>${field('Cidade','city',a.city,'text','required autocomplete="address-level2"')}</div><div>${field('UF','state',a.state,'text','required minlength="2" maxlength="2" autocomplete="address-level1"')}</div></div>`;}
async function checkout(){if(!cart.length){location.hash='catalog';return;}const q=await api('/quote','POST',{items:cart,coupon});main.innerHTML=`<section class="wrap page"><div class="breadcrumb"><a href="#home">Início</a> / Sacola / Pedido pelo WhatsApp</div><h1>Vamos combinar pelo WhatsApp?</h1><p class="small-text">Escolha como deseja pagar e confira sua mensagem. O pedido será confirmado pela loja no atendimento.</p><div class="checkout-grid"><form id="checkout" class="form"><div class="panel"><h2>01. Seus dados</h2>${field('Seu nome','name',user?.name||'','text','required maxlength="100" autocomplete="name"')}${field('Seu telefone (opcional)','phone',user?.phone||'','tel','maxlength="30" autocomplete="tel"')}<label for="delivery-address">Endereço de entrega ou preferência de retirada (opcional)</label><textarea id="delivery-address" name="address" maxlength="500" placeholder="Rua, número, bairro, cidade e CEP — ou informe que deseja retirar"></textarea></div><div class="panel"><h2>02. Como deseja pagar?</h2><label class="check-label"><input type="radio" name="payment" value="pix" checked> Pix</label><label class="check-label"><input type="radio" name="payment" value="card"> Cartão — combinar com a loja</label><label class="check-label"><input type="radio" name="payment" value="cash"> Dinheiro — combinar com a loja</label><p class="small-text">O pagamento será combinado diretamente no atendimento.</p><label for="order-notes">Observações (opcional)</label><textarea id="order-notes" name="notes" maxlength="500" placeholder="Conte se precisa de alguma informação adicional"></textarea></div><p class="error" id="checkout-error" role="alert"></p><button class="btn">Conferir mensagem do pedido ↗</button></form><aside><div class="panel"><h2>Sua escolha</h2>${q.items.map(i=>`<div class="cart-line"><img src="${esc(i.image||store.products.find(p=>p.id===i.productId)?.images[0])}" alt="${esc(i.name)}"><div><h3>${esc(i.name)}</h3><p>Tam. ${esc(i.size)} • ${i.quantity} unidade(s)</p></div><strong>${money(i.price*i.quantity)}</strong></div>`).join('')}<div class="summary">${totalsHTML(q)}</div><div class="notice">Frete e disponibilidade serão confirmados pelo WhatsApp. O envio da mensagem não confirma pagamento nem reserva estoque.</div></div><button class="btn light" data-action="cart">Revisar sacola</button></aside></div></section>`;}
const adminSections={products:'Tênis',stock:'Estoque',customers:'Clientes',settings:'Loja'};
const stockTotal=p=>Object.values(p.sizes).reduce((a,b)=>a+b,0);
const customerDate=value=>value?new Date(value).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short',timeZone:'America/Sao_Paulo'}):'Não registrado';
function adminCustomers(){return admin.customers.filter(u=>u.role!=='admin').sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));}
const roleName={owner:'Dono',manager:'Gerente',admin:'ADM'};
function passwordForm(){return `<form id="staff-password" class="form panel"><span class="eyebrow">SEGURANÇA GYM STORE</span><h1>${user.mustChangePassword?'Crie sua senha pessoal':'Trocar minha senha'}</h1><p>Use pelo menos 12 caracteres. Escolha uma senha exclusiva para sua conta.</p>${field('Senha atual','currentPassword','','password','required autocomplete="current-password" maxlength="128"')}${field('Nova senha','password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}${field('Confirme a nova senha','confirmation','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<p class="error" id="form-error" role="alert"></p><button class="btn">Salvar nova senha</button><button type="button" class="btn light" data-action="logout">Sair</button></form>`;}
async function adminPage(){if(!user||!roleName[user.role]){main.innerHTML=`<section class="wrap page admin-login"><img src="/assets/logo.webp" alt="GYM STORE" width="90" height="90"><span class="eyebrow">ADMINISTRAÇÃO GYM STORE</span><h1>Sua loja, bem cuidada.</h1><p>Acesso exclusivo para quem administra a GYM STORE.</p><form id="staff-login" class="form panel">${field('Login','identifier','','text','required autocomplete="username" maxlength="200" autocapitalize="none" spellcheck="false"')}${field('Senha','password','','password','required autocomplete="current-password" maxlength="128"')}<p class="error" id="form-error" role="alert"></p><button class="btn">Entrar no painel</button></form><a href="#home">Voltar para a loja</a></section>`;return;}if(user.mustChangePassword){main.innerHTML=`<section class="wrap page admin-login">${passwordForm()}</section>`;return;}
admin=await api('/admin');if(!(admin.permissions||Object.keys(adminSections)).includes(adminTab))adminTab='products';main.innerHTML=`<section class="admin-shell"><aside class="admin-sidebar"><a class="admin-wordmark" href="#admin"><img src="/assets/logo.webp" alt="Logo GYM STORE"><span>GYM STORE<small>ADMINISTRAÇÃO</small></span></a><nav class="admin-navigation" aria-label="Menu do painel">${Object.entries(adminSections).filter(([id])=>(admin.permissions||Object.keys(adminSections)).includes(id)).map(([id,label])=>`<button class="${adminTab===id?'active':''}" data-action="admin-tab" data-tab="${id}" ${adminTab===id?'aria-current="page"':''}><span class="admin-nav-dot" aria-hidden="true"></span>${label}</button>`).join('')}</nav><a class="admin-store-link" href="#home">Ver loja ↗</a><button class="admin-signout" data-action="password-change">Trocar minha senha</button><button class="admin-signout" data-action="logout">Sair da conta</button></aside><div class="admin-main"><div class="admin-top"><div><span class="eyebrow">GYM STORE / PAINEL</span><h1>${adminSections[adminTab]}</h1></div><div class="admin-user"><button class="admin-reload" data-action="admin-reload" aria-label="Atualizar dados do painel" title="Atualizar painel">↻</button><span class="admin-avatar">${esc(user.name[0].toUpperCase())}</span><span>${esc(user.name)}<small>${roleName[user.role]}</small></span></div></div><div id="admin-content"></div></div></section>`;renderAdmin();}
function renderAdmin(){const target=$('#admin-content');const customers=adminCustomers();const low=admin.products.filter(p=>p.active&&stockTotal(p)<=5);const today=new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'});const recent=customers.filter(u=>u.createdAt&&new Date(u.createdAt).toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'})===today);
if(adminTab==='overview'){target.innerHTML=`<div class="admin-greeting"><h2>Olá, ${esc(user.name.split(' ')[0])}.</h2><p>Seus produtos e clientes, tudo em um só lugar.</p><button class="btn" data-action="edit-product">+ Adicionar tênis</button></div><div class="admin-stats"><button class="admin-stat" data-action="admin-tab" data-tab="products"><span>Tênis na loja</span><b>${admin.products.filter(p=>p.active).length}</b><small>${admin.products.length} cadastrados ao todo</small></button><button class="admin-stat" data-action="admin-tab" data-tab="customers"><span>Clientes cadastrados</span><b>${customers.length}</b><small>${recent.length} novo(s) hoje</small></button><button class="admin-stat" data-action="admin-tab" data-tab="stock"><span>Unidades no estoque</span><b>${admin.products.reduce((n,p)=>n+stockTotal(p),0)}</b><small>Somadas por numeração</small></button><button class="admin-stat ${low.length?'attention':''}" data-action="admin-tab" data-tab="stock"><span>Estoque baixo</span><b>${low.length}</b><small>Modelos com até 5 unidades</small></button></div><div class="admin-overview-grid"><div class="admin-card"><div class="admin-card-title"><h2>Cadastros mais recentes</h2><button data-action="admin-tab" data-tab="customers">Ver todos</button></div>${customers.length?customers.slice(0,5).map(u=>`<div class="admin-customer-line"><span class="admin-avatar">${esc(u.name[0].toUpperCase())}</span><div><b>${esc(u.name)}</b><small>${esc(u.email)}</small></div><time>${customerDate(u.createdAt)}</time></div>`).join(''):'<div class="admin-empty">Os novos cadastros da loja aparecerão aqui.</div>'}</div><div class="admin-card"><h2>Organize sua loja</h2><button class="admin-shortcut" data-action="admin-tab" data-tab="products"><b>Cadastre seus tênis</b><span>Fotos, nomes, preços e numerações →</span></button><button class="admin-shortcut" data-action="admin-tab" data-tab="settings"><b>${admin.whatsappNumber?'WhatsApp configurado':'Configure seu WhatsApp'}</b><span>Escolha onde receber os pedidos →</span></button><button class="admin-shortcut" data-action="admin-tab" data-tab="banners"><b>Personalize seu banner</b><span>Troque a imagem e os textos →</span></button></div></div><div class="admin-note">Os pedidos são combinados pelo WhatsApp. A loja não confirma automaticamente mensagens enviadas, pagamentos ou baixas de estoque. Atualize o estoque quando confirmar a venda.</div>`;return;}
if(adminTab==='products'){target.innerHTML=`<div class="admin-toolbar"><div class="admin-search-box"><label class="sr" for="admin-product-query">Buscar tênis no painel</label><input type="search" id="admin-product-query" placeholder="Buscar tênis pelo nome..."></div><select id="admin-product-status" aria-label="Filtrar visibilidade"><option value="all">Todos os produtos</option><option value="active">Visíveis na loja</option><option value="hidden">Ocultos</option></select><button class="btn" data-action="edit-product">+ Adicionar tênis</button></div><div id="admin-product-list" class="admin-product-list"></div>`;renderAdminProductList();$('#admin-product-query').oninput=renderAdminProductList;$('#admin-product-status').onchange=renderAdminProductList;return;}
if(adminTab==='customers'){target.innerHTML=`<div class="admin-toolbar"><input type="search" id="admin-customer-query" placeholder="Buscar cliente por nome, e-mail ou telefone" aria-label="Buscar clientes"><span class="small-text">${customers.length} cliente(s) cadastrado(s)</span></div><div class="admin-card" id="admin-customer-list"></div><p class="small-text">Cadastros anteriores a esta atualização podem aparecer sem data. Senhas nunca são exibidas.</p>`;renderAdminCustomerList();$('#admin-customer-query').oninput=renderAdminCustomerList;return;}
if(adminTab==='stock'){target.innerHTML=`<div class="admin-toolbar"><input type="search" id="admin-stock-query" placeholder="Buscar tênis para ajustar o estoque" aria-label="Buscar estoque"></div><div class="admin-note">Informe a quantidade disponível de cada numeração e salve o modelo. Use 0 para um tamanho esgotado. As mudanças aparecem na loja.</div><div id="admin-stock-list"></div>`;renderAdminStock();$('#admin-stock-query').oninput=renderAdminStock;return;}
if(adminTab==='settings'){target.innerHTML=`<div class="admin-card admin-narrow"><form class="form" id="admin-whatsapp"><h2>WhatsApp da loja</h2><p class="small-text">É neste número que você vai receber os pedidos.</p>${field('Número com país e DDD','number',admin.whatsappNumber||'','tel','required pattern="[0-9]{10,15}" placeholder="55 + DDD + número"')}<button class="btn">Salvar WhatsApp</button></form></div><details class="admin-card admin-narrow admin-optional"><summary>Alterar banner da loja</summary><form class="form" id="admin-banner">${field('Chamada superior','eyebrow',admin.banners.eyebrow,'text','required maxlength="80"')}<label for="banner-title">Título</label><textarea id="banner-title" name="title" required maxlength="150">${esc(admin.banners.title)}</textarea>${field('Texto de apoio','subtitle',admin.banners.subtitle,'text','required maxlength="250"')}<label for="banner-upload">Trocar foto do banner</label><input type="file" id="banner-upload" accept="image/jpeg,image/png,image/webp">${field('Imagem atual','image',admin.banners.image,'text','required')}<img id="admin-banner-image" class="admin-settings-photo" src="${esc(admin.banners.image)}" alt="Banner da loja"><button class="btn">Salvar banner</button></form></details><button class="admin-simple-signout" data-action="logout">Sair da minha conta</button>`;return;}
if(adminTab==='banners'){target.innerHTML=`<div class="admin-banner-layout"><div class="admin-card"><form class="form" id="admin-banner"><h2>Banner de boas-vindas</h2>${field('Nome ou chamada superior','eyebrow',admin.banners.eyebrow,'text','required maxlength="80"')}<label for="banner-title">Título</label><textarea id="banner-title" name="title" required maxlength="150">${esc(admin.banners.title)}</textarea>${field('Texto de apoio','subtitle',admin.banners.subtitle,'text','required maxlength="250"')}<label for="banner-upload">Enviar imagem (JPG, PNG ou WebP, até 800 KB)</label><input type="file" id="banner-upload" accept="image/jpeg,image/png,image/webp">${field('Ou colar o endereço da imagem','image',admin.banners.image,'text','required')}<button class="btn">Salvar banner</button></form></div><div class="admin-card admin-banner-preview"><h2>Imagem atual</h2><img id="admin-banner-image" src="${esc(admin.banners.image)}" alt="Prévia do banner"><p class="small-text">O texto fica separado da foto na loja. Prefira uma imagem com o tênis inteiro e fundo simples.</p></div></div>`;return;}
if(adminTab==='coupons'){target.innerHTML=`<div class="admin-overview-grid"><div class="admin-card"><h2>Cupons cadastrados</h2>${admin.coupons.length?admin.coupons.map((c,i)=>`<div class="admin-coupon"><div><b>${esc(c.code)}</b><small>${c.percent}% de desconto · mínimo ${money(c.minimum)}</small></div><button class="admin-toggle" data-action="toggle-coupon" data-index="${i}">${c.active?'Ativo · desativar':'Inativo · ativar'}</button></div>`).join(''):'<div class="admin-empty">Nenhum cupom cadastrado.</div>'}</div><div class="admin-card"><form class="form" id="admin-new-coupon"><h2>Criar ou atualizar cupom</h2>${field('Código do cupom','code','','text','required pattern="[A-Za-z0-9_-]{2,30}" maxlength="30" placeholder="Ex.: GYM10"')}<div class="two"><div>${field('Desconto (%)','percent',10,'number','required min="1" max="80" step="1"')}</div><div>${field('Compra mínima (R$)','minimum',0,'number','required min="0" step="0.01"')}</div></div><button class="btn">Salvar cupom</button></form></div></div>`;return;}
if(adminTab==='categories'){target.innerHTML=`<div class="admin-card admin-narrow"><h2>Categorias da loja</h2>${admin.categories.map((c,i)=>`<div class="admin-coupon"><div><b>${esc(c)}</b><small>${admin.products.filter(p=>p.category===c).length} produto(s)</small></div><button data-action="remove-category" data-index="${i}">Remover</button></div>`).join('')}<form class="form" id="admin-new-category">${field('Nova categoria','category','','text','required maxlength="50" placeholder="Nome da categoria"')}<button class="btn">Adicionar categoria</button></form><p class="small-text">Uma categoria só pode ser removida se não tiver produtos vinculados.</p></div>`;}
}
function renderAdminProductList(){const q=$('#admin-product-query').value,status=$('#admin-product-status').value;const products=admin.products.filter(p=>matchesShoeSearch(p,q)&&(status==='all'||(status==='active'?p.active:!p.active)));$('#admin-product-list').innerHTML=products.length?products.map(p=>`<article class="admin-product-card"><img src="${esc(p.images[0])}" alt="${esc(p.name)}"><div class="admin-product-info"><span class="admin-status ${p.active?'visible':'hidden'}">${p.active?'Visível na loja':'Oculto'}</span><h2>${esc(p.name)}</h2><p>${esc(p.category)} · ${esc(p.color)}</p><strong>${money(p.price)}</strong><p class="admin-size-summary">${Object.entries(p.sizes).map(([k,v])=>`${k}: ${v}`).join(' · ')}</p><span class="small-text">${stockTotal(p)} unidade(s) no estoque</span></div><div class="admin-product-actions"><button class="btn light" data-action="edit-product" data-id="${p.id}">Editar tênis</button><button class="admin-toggle" data-action="toggle-product" data-id="${p.id}">${p.active?'Ocultar da loja':'Mostrar na loja'}</button></div></article>`).join(''):'<div class="admin-empty">Nenhum tênis encontrado.</div>';}
function renderAdminCustomerList(){const q=normalizeSearch($('#admin-customer-query').value);const customers=adminCustomers().filter(u=>normalizeSearch(u.name+' '+u.email+' '+u.phone).includes(q));$('#admin-customer-list').innerHTML=customers.length?customers.map(u=>`<article class="admin-client-card"><div class="admin-client-heading"><span class="admin-avatar">${esc(u.name[0].toUpperCase())}</span><div><h2>${esc(u.name)}</h2><span class="small-text">Cadastro: ${customerDate(u.createdAt)}</span></div></div><dl><div><dt>E-mail</dt><dd>${esc(u.email)}</dd></div><div><dt>Telefone</dt><dd>${esc(u.phone||'Não informado')}</dd></div><div><dt>Endereços salvos</dt><dd>${u.addresses.length}</dd></div><div><dt>Último acesso</dt><dd>${customerDate(u.lastLoginAt)}</dd></div></dl></article>`).join(''):'<div class="admin-empty">Nenhum cadastro encontrado.</div>';}
function renderAdminStock(){const q=$('#admin-stock-query').value;$('#admin-stock-list').innerHTML=admin.products.filter(p=>matchesShoeSearch(p,q)).map(p=>`<form class="admin-card admin-stock-form" data-id="${p.id}"><div class="admin-card-title"><div><h2>${esc(p.name)}</h2><span class="small-text">${stockTotal(p)} unidade(s) · ${p.active?'Visível':'Oculto'}</span></div><button class="btn light">Salvar estoque</button></div><div class="admin-stock-grid">${Object.entries(p.sizes).map(([size,n])=>`<label><span>Tam. ${size}</span><input type="number" name="size_${size}" value="${n}" min="0" max="100000" step="1" required aria-label="Estoque tamanho ${size}"></label>`).join('')}</div></form>`).join('')||'<div class="admin-empty">Nenhum tênis encontrado.</div>';}
function editProduct(id){const p=admin.products.find(p=>p.id===id)||{name:'',category:admin.categories[0],price:0,oldPrice:0,color:'',images:[],description:'',sizes:{},active:true,tag:''};const sizes=[...new Set([...Array.from({length:15},(_,i)=>String(i+32)),...Object.keys(p.sizes)])].sort((a,b)=>Number(a)-Number(b));show(`<form class="admin-product-form" id="edit-product" data-id="${esc(p.id||'')}"><span class="eyebrow">CATÁLOGO GYM STORE</span><h2>${p.id?'Editar tênis':'Adicionar tênis'}</h2><p class="small-text">Preencha os dados que seus clientes verão na loja.</p><div class="admin-form-section form"><h3>01. Informações do tênis</h3>${field('Nome do tênis','name',p.name,'text','required maxlength="100" placeholder="Ex.: Nike Air Force 1 Branco"')}<div class="admin-category-row"><div><label>Categoria</label><div class="admin-category-choices">${admin.categories.map(c=>`<label class="admin-category-choice"><input type="radio" name="category" value="${esc(c)}" ${p.category===c?'checked':''} required><span>${esc(c)}</span></label>`).join('')}</div></div><div>${field('Cor','color',p.color,'text','required maxlength="50" placeholder="Ex.: Branco e preto"')}</div></div><div class="two"><div>${field('Preço de venda (R$)','price',p.price?p.price/100:'','number','required min="1" step="0.01"')}</div><div>${field('Preço anterior (R$, opcional)','oldPrice',p.oldPrice?p.oldPrice/100:'','number','min="0" step="0.01"')}</div></div><input type="hidden" name="tag" value="${esc(p.tag)}"><label>Descrição</label><textarea name="description" required maxlength="3000" placeholder="Descreva o modelo, acabamento e detalhes importantes.">${esc(p.description)}</textarea></div><div class="admin-form-section form"><h3>02. Fotos do produto</h3><p class="small-text">Adicione até 5 fotos. Pode escolher várias de uma vez ou acrescentar uma por vez. A primeira é a capa.</p><label class="admin-upload-label" for="product-upload">+ Adicionar fotos do tênis</label><input type="file" id="product-upload" accept="image/jpeg,image/png,image/webp" multiple><p id="admin-photo-count" class="admin-photo-count" aria-live="polite"></p><div id="admin-photo-preview" class="admin-photo-preview"></div><details class="admin-photo-links"><summary>Usar fotos por link</summary><label for="product-images">Uma imagem por linha</label><textarea name="images" id="product-images">${esc(p.images.join('\n'))}</textarea><button type="button" class="btn light" data-action="refresh-photos">Atualizar prévia</button></details></div><div class="admin-form-section form"><h3>03. Tamanhos e estoque</h3><p class="small-text">Informe a quantidade por tamanho. Campo vazio = não vendido; 0 = esgotado.</p><div class="admin-stock-grid">${sizes.map(size=>`<label><span>Tam. ${size}</span><input type="number" name="size_${size}" value="${Object.hasOwn(p.sizes,size)?p.sizes[size]:''}" min="0" max="100000" step="1" placeholder="—" aria-label="Estoque tamanho ${size}"></label>`).join('')}</div><details class="admin-extra-size"><summary>Adicionar outra numeração</summary><div class="two"><div>${field('Tamanho adicional','extraSize','','number','min="10" max="99" step="1"')}</div><div>${field('Quantidade','extraQuantity','','number','min="0" max="100000" step="1"')}</div></div></details></div><div class="admin-form-section form"><label class="check-label"><input name="active" type="checkbox" ${p.active?'checked':''}> Mostrar este tênis na loja</label><p class="error" id="admin-product-error" role="alert"></p><button class="btn admin-save-product">Salvar tênis</button><p class="small-text">A alteração fica disponível na loja assim que você salvar.</p></div></form>`);renderProductPhotos();}
function renderProductPhotos(){const input=$('#product-images');if(!input)return;const images=input.value.split('\n').map(x=>x.trim()).filter(Boolean);$('#admin-photo-count').textContent=images.length+' de 5 fotos adicionadas';$('#admin-photo-preview').innerHTML=images.length?images.map((url,i)=>`<div><img src="${esc(url)}" alt="Foto ${i+1} do tênis"><span>${i===0?'Capa':'Foto '+(i+1)}</span><button type="button" data-action="remove-product-photo" data-index="${i}" aria-label="Remover foto ${i+1}">×</button>${i?`<button type="button" class="photo-cover" data-action="cover-product-photo" data-index="${i}">Usar como capa</button>`:''}</div>`).join(''):'<p class="small-text">As fotos selecionadas aparecerão aqui.</p>';}
async function refreshStore(){store=await api('/store');}
async function route(){if(!store)return;const hash=location.hash.slice(1)||'home';const [page,query='']=hash.split('?');document.body.classList.toggle('admin-view',page==='admin');try{if(page.startsWith('product=')){if(!main.innerHTML)home();detail(page.slice(8));return;}if(modal.open)modal.close();main.innerHTML='<div class="loading">Carregando…</div>';if(page==='catalog')catalog(new URLSearchParams(query));else if(page==='account')await account();else if(page==='checkout')await checkout();else if(page==='admin')await adminPage();else if(page.startsWith('reset=')){home();show(`<form class="form" id="reset" data-token="${esc(page.slice(6))}"><h2>Crie sua nova senha</h2>${field('Nova senha (mínimo 10 caracteres)','password','','password','required minlength="10" maxlength="128" autocomplete="new-password"')}<p class="error" id="form-error"></p><button class="btn">Redefinir senha</button></form>`);}else home();window.scrollTo({top:0});}catch(e){main.innerHTML=`<div class="wrap page"><h1>Não foi possível carregar.</h1><p>${esc(e.message)}</p><a class="btn" href="#home">Voltar para a loja</a></div>`;}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;try{
if(a==='close'){modal.close();if(location.hash.startsWith('#product='))history.replaceState(null,'','#home');}
if(a==='copy-order'){await navigator.clipboard.writeText($('#whatsapp-message').value);toast('Mensagem copiada.');}if(a==='cart')await openCart();if(a==='account'){location.hash='account';if(!user)auth();}if(a==='auth')auth(el.dataset.mode);if(a==='shop'){modal.close();location.hash='catalog';}
if(a==='clear-shoe-search'){const input=$('#shoe-search')||$('#catalog-name-search');if(input){input.value='';input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();}}if(a==='size'){chosenSize=el.dataset.size;document.querySelectorAll('.size').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',String(b===el));});$('#selected-size').textContent='Tamanho '+chosenSize;$('.detail-size-hint').textContent='Tamanho '+chosenSize+' selecionado';const p=store.products.find(p=>p.id===detailId);const input=$('#quantity');input.value=Math.min(Number(input.value),p.sizes[chosenSize]);$('#detail-line-total').textContent=money(p.price*Number(input.value));}
if(a==='detail-qty'){const p=store.products.find(p=>p.id===detailId),input=$('#quantity');const max=chosenSize?Math.min(20,p.sizes[chosenSize]):20;input.value=Math.max(1,Math.min(max,Number(input.value)+Number(el.dataset.delta)));$('#detail-line-total').textContent=money(p.price*Number(input.value));}
if(a==='photo'){$('.detail-image').src=store.products.find(p=>p.id===detailId).images[Number(el.dataset.index)];document.querySelectorAll('.gallery button').forEach(b=>{b.classList.toggle('selected',b===el);b.setAttribute('aria-pressed',String(b===el));});}
if(a==='add'){if(!chosenSize){toast('Escolha a numeração do seu tênis.');return;}const quantity=Number($('#quantity').value),p=store.products.find(p=>p.id===detailId);const item=cart.find(x=>x.productId===detailId&&x.size===chosenSize);if(quantity+(item?.quantity||0)>p.sizes[chosenSize]){toast('Quantidade maior que o estoque disponível.');return;}if(item)item.quantity+=quantity;else cart.push({productId:detailId,size:chosenSize,quantity});persist();await openCart();}
if(a==='qty'){const i=Number(el.dataset.index),n=cart[i].quantity+Number(el.dataset.delta);if(n<=0)cart.splice(i,1);else{const p=store.products.find(p=>p.id===cart[i].productId);if(n>20||!p||n>p.sizes[cart[i].size]){toast('Limite de estoque atingido.');return;}cart[i].quantity=n;}persist();await openCart();}
if(a==='remove'){cart.splice(Number(el.dataset.index),1);persist();await openCart();}if(a==='clear-coupon'){coupon='';await openCart();}
if(a==='checkout'){modal.close();location.hash='checkout';if(location.hash==='#checkout')await checkout();}
if(a==='home-filter'){document.querySelectorAll('[data-action="home-filter"]').forEach(x=>x.classList.toggle('active',x===el));renderHomeProducts();}
if(a==='logout'){await api('/auth/logout','POST',{});user=null;location.hash='home';toast('Você saiu da conta.');}
if(a==='address')show(`<form class="form" id="address"><h2>Novo endereço</h2>${addressFields()}<button class="btn">Salvar endereço</button></form>`);
if(a==='delete-address'){user=(await api('/profile','PUT',{...user,addresses:user.addresses.filter((_,i)=>i!==Number(el.dataset.index))})).user;await account();}
if(a==='password-change')show(passwordForm());if(a==='admin-reload'){await adminPage();toast('Painel atualizado.');}if(a==='toggle-product'){const p=admin.products.find(x=>x.id===el.dataset.id);await api('/admin/product','PUT',{...p,active:!p.active});await refreshStore();await adminPage();toast(p.active?'Tênis ocultado da loja.':'Tênis visível na loja.');}
if(a==='toggle-coupon'){const coupons=admin.coupons.map((c,i)=>i===Number(el.dataset.index)?{...c,active:!c.active}:c);await api('/admin/coupons','PUT',{coupons});await adminPage();toast('Cupom atualizado.');}
if(a==='remove-category'){const categories=admin.categories.filter((_,i)=>i!==Number(el.dataset.index));await api('/admin/categories','PUT',{categories});await refreshStore();await adminPage();toast('Categoria removida.');}
if(a==='refresh-photos')renderProductPhotos();
if(a==='remove-product-photo'||a==='cover-product-photo'){const input=$('#product-images'),images=input.value.split('\n').filter(x=>x.trim());const i=Number(el.dataset.index);if(a==='remove-product-photo')images.splice(i,1);else images.unshift(...images.splice(i,1));input.value=images.join('\n');renderProductPhotos();}
if(a==='admin-tab'){adminTab=el.dataset.tab;await adminPage();}if(a==='edit-product')editProduct(el.dataset.id);
if(a==='info'){const data={atendimento:['Atendimento','Os canais de WhatsApp, e-mail e Instagram da GYM STORE ainda serão informados pelo responsável. Nenhum contato fictício foi publicado.'],trocas:['Trocas e devoluções','Esta é uma demonstração sem vendas reais. A política de trocas, prazos, endereço de devolução e canais de suporte deverão ser definidos antes do lançamento.'],privacidade:['Privacidade','Usamos um cookie essencial para manter sua sessão e armazenamento local para sua sacola. Os dados cadastrais são armazenados no banco da loja. Nesta prévia, use dados fictícios. A identificação do responsável e a política completa deverão ser revisadas antes da publicação.']};const [title,text]=data[el.dataset.topic];show(`<h2>${title}</h2><p class="small-text">${text}</p>`);}
}catch(e){toast(e.message);}});
document.addEventListener('submit',async e=>{const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();const v=Object.fromEntries(new FormData(f)),btn=f.querySelector('button[type="submit"],button:not([type])');if(btn)btn.disabled=true;try{
if(f.id==='staff-login'){const data=await api('/auth/login','POST',v);user=data.user;if(!roleName[user.role])throw Error('Esta conta não possui acesso ao painel.');await route();}
if(f.id==='staff-password'){if(v.password!==v.confirmation)throw Error('As senhas não coincidem.');user=(await api('/auth/change-password','POST',v)).user;if(modal.open)modal.close();await route();toast('Senha atualizada com segurança.');}
if(f.id==='search'){location.hash='catalog?q='+encodeURIComponent(v.q);}
if(f.id==='auth'){const mode=f.dataset.mode;const data=await api('/auth/'+(mode==='register'?'register':mode==='forgot'?'forgot':'login'),'POST',v);if(mode==='forgot')toast(data.message);else{user=data.user;modal.close();toast('Bem-vindo à GYM STORE.');await route();}}
if(f.id==='reset'){await api('/auth/reset','POST',{...v,token:f.dataset.token});modal.close();toast('Senha atualizada. Entre novamente.');auth();}
if(f.id==='coupon'){coupon=v.coupon.toUpperCase().trim();await openCart();}
if(['product-shipping','cart-shipping'].includes(f.id)){const rates=await api('/shipping','POST',{cep:v.cep,items:cart.length?cart:[{productId:detailId,size:chosenSize||Object.keys(store.products.find(p=>p.id===detailId).sizes)[0],quantity:1}]});toast(rates.rates.map(r=>r.name+': '+money(r.price)+' / '+r.days+' dias').join(' • ')||'Sem entregas disponíveis para este CEP.');}
if(f.id==='admin-whatsapp'){await api('/admin/settings','PUT',{whatsappNumber:v.number});await refreshStore();await adminPage();toast('WhatsApp atualizado.');}if(f.id==='profile'){user=(await api('/profile','PUT',v)).user;toast('Dados salvos.');}
if(f.id==='address'){user=(await api('/profile','PUT',{...user,addresses:[...user.addresses,v]})).user;modal.close();await account();toast('Endereço salvo.');}
if(f.id==='checkout'){const q=await api('/quote','POST',{items:cart,coupon});const message=buildWhatsAppMessage(q,v);let link='';try{link=whatsappURL(store.whatsappNumber,message);}catch{}show(`<div class="form"><h2>Confira seu pedido.</h2><p class="small-text">O WhatsApp abrirá com esta mensagem preenchida. Toque em Enviar na conversa para encaminhar à loja.</p><label for="whatsapp-message">Mensagem do pedido</label><textarea id="whatsapp-message" class="field" rows="16" readonly>${esc(message)}</textarea>${link?`<a class="btn whatsapp-btn" href="${esc(link)}" target="_blank" rel="noopener noreferrer">Abrir WhatsApp com meu pedido ↗</a>`:'<div class="notice">Falta configurar o número de WhatsApp da GYM STORE. Sua mensagem está pronta para conferência.</div>'}<button type="button" class="btn light" data-action="copy-order">Copiar mensagem</button><p class="small-text">Sua sacola continuará salva. A loja confirmará disponibilidade, entrega e pagamento no atendimento.</p></div>`);}
if(f.id==='edit-product'){const sizes={};for(const [key,value]of Object.entries(v)){if(key.startsWith('size_')&&value!=='')sizes[key.slice(5)]=Number(value);}if(v.extraSize){if(v.extraQuantity==='')throw Error('Informe a quantidade do tamanho adicional.');sizes[v.extraSize]=Number(v.extraQuantity);}if(!Object.keys(sizes).length)throw Error('Preencha o estoque de pelo menos um tamanho.');const images=v.images.split('\n').map(x=>x.trim()).filter(Boolean);if(!images.length||images.length>5)throw Error('Adicione de 1 a 5 fotos.');await api('/admin/product','PUT',{name:v.name,category:v.category,color:v.color,description:v.description,tag:v.tag,id:f.dataset.id||undefined,price:Math.round(Number(v.price)*100),oldPrice:Math.round(Number(v.oldPrice||0)*100),images,sizes,package:admin.products.find(p=>p.id===f.dataset.id)?.package,active:!!v.active});modal.close();await refreshStore();await adminPage();toast('Tênis salvo. Alteração disponível na loja.');}
if(f.matches('.admin-stock-form')){const p=admin.products.find(p=>p.id===f.dataset.id);const sizes=Object.fromEntries(Object.entries(v).filter(([k])=>k.startsWith('size_')).map(([k,n])=>[k.slice(5),Number(n)]));await api('/admin/product','PUT',{...p,sizes});await refreshStore();await adminPage();toast('Estoque atualizado na loja.');}
if(f.id==='admin-new-category'){await api('/admin/categories','PUT',{categories:[...admin.categories,v.category.trim()]});await refreshStore();await adminPage();toast('Categoria adicionada.');}
if(f.id==='admin-new-coupon'){const coupon={code:v.code.trim().toUpperCase(),percent:Number(v.percent),minimum:Math.round(Number(v.minimum)*100),active:true};const coupons=admin.coupons.filter(c=>c.code!==coupon.code);coupons.push(coupon);await api('/admin/coupons','PUT',{coupons});await adminPage();toast('Cupom salvo.');}
if(f.id==='admin-banner'){await api('/admin/banner','PUT',v);await refreshStore();await adminPage();toast('Banner atualizado na loja.');}
if(f.id==='admin-categories'){await api('/admin/categories','PUT',{categories:v.rows.split('\n').map(x=>x.trim()).filter(Boolean)});await refreshStore();await adminPage();toast('Categorias salvas.');}
if(f.id==='admin-coupons'){const coupons=v.rows.split('\n').filter(x=>x.trim()).map(row=>{const [code,percent,minimum,active]=row.split(';').map(x=>x.trim());return {code:code.toUpperCase(),percent:Number(percent),minimum:Math.round(Number(minimum.replace(',','.'))*100),active:active==='sim'};});await api('/admin/coupons','PUT',{coupons});await adminPage();toast('Cupons salvos.');}
}catch(err){const target=f.querySelector('#form-error,#checkout-error,#admin-product-error');if(target)target.textContent=err.message;else toast(err.message);}finally{if(btn)btn.disabled=false;}});
async function prepareProductPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Escolha fotos JPG, PNG ou WebP.');if(file.size>20000000)throw Error('Escolha uma foto com até 20 MB.');const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('Não foi possível abrir esta foto.'));image.src=url;});const canvas=document.createElement('canvas');let edge=1400;let data='';for(let round=0;round<3;round++){const scale=Math.min(1,edge/Math.max(img.naturalWidth,img.naturalHeight));canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(img,0,0,canvas.width,canvas.height);data=canvas.toDataURL('image/jpeg',round===0?.84:.72);if(data.length<600000)return data;edge-=300;}if(data.length>1000000)throw Error('A foto é muito grande. Tente outra imagem.');return data;}finally{URL.revokeObjectURL(url);}}
document.addEventListener('change',async e=>{const el=e.target;try{if(el.matches('.order-status')){await api('/admin/order','PUT',{id:el.dataset.id,status:el.value});toast('Status atualizado.');}if(['product-upload','banner-upload'].includes(el.id)){const files=[...el.files];if(!files.length)return;if(files.length>5)throw Error('Selecione até 5 fotos.');const input=$('#product-images');const current=el.id==='product-upload'?input.value.split('\n').filter(x=>x.trim()):[];if(el.id==='product-upload'&&current.length+files.length>5)throw Error('Você pode ter até 5 fotos. Remova uma para adicionar outra.');el.disabled=true;toast('Preparando '+files.length+' foto(s)...');const data=[];for(const file of files)data.push(await prepareProductPhoto(file));if(el.id==='product-upload'){const all=[...new Set(current.concat(data))];if(all.join('').length>3500000)throw Error('As fotos ficaram muito grandes. Use fotos menores.');input.value=all.join('\n');renderProductPhotos();toast(data.length+' foto(s) adicionada(s).');}else{$('#admin-banner').elements.image.value=data[0];$('#admin-banner-image').src=data[0];toast('Foto do banner atualizada. Clique em salvar.');}el.value='';}}catch(e){toast(e.message);}finally{if(['product-upload','banner-upload'].includes(el.id))el.disabled=false;}});
window.addEventListener('hashchange',route);modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
(async()=>{persist();try{[store,{user}]=await Promise.all([api('/store'),api('/me')]);await route();}catch(e){main.innerHTML='<div class="wrap page"><h1>Estamos preparando seus próximos passos.</h1><p>Não foi possível conectar ao servidor. Inicie o projeto com npm run dev e configure o banco de dados.</p></div>';}})();

